import fs, { constants } from 'fs/promises';
import path from 'path';
import { createHash } from 'crypto';
import type { VariantWorkItemContext } from '../agent-variants/contracts';
import {
  referenceImageSchema,
  type ReferenceImageDescriptor,
  type VariantReference,
} from '../types/variant-reference';
import { errnoCode } from '../utils/errnoCode';
import { isPathStrictlyInsideRoot } from '../utils/pathContainment';

export type ReferenceImage = { body: Buffer; mimeType: string };
const MAX_REFERENCE_IMAGE_BYTES = 35 * 1024 * 1024;

const matchesImageType = (body: Buffer, mimeType: string): boolean => {
  switch (mimeType) {
    case 'image/png':
      return body
        .subarray(0, 8)
        .equals(Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]));
    case 'image/jpeg':
      return body[0] === 255 && body[1] === 216 && body[2] === 255;
    case 'image/gif':
      return ['GIF87a', 'GIF89a'].includes(
        body.subarray(0, 6).toString('ascii'),
      );
    case 'image/webp':
      return (
        body.subarray(0, 4).toString('ascii') === 'RIFF' &&
        body.subarray(8, 12).toString('ascii') === 'WEBP'
      );
    case 'image/avif':
      return (
        body.subarray(4, 8).toString('ascii') === 'ftyp' &&
        ['avif', 'avis'].includes(body.subarray(8, 12).toString('ascii'))
      );
    default:
      return false;
  }
};

export const readReferenceImage = async (args: {
  root: string;
  filePath: string;
  image: ReferenceImageDescriptor;
}): Promise<ReferenceImage | null> => {
  if (!referenceImageSchema.safeParse(args.image).success) return null;
  const root = path.resolve(args.root);
  const filePath = path.resolve(args.filePath);
  if (!isPathStrictlyInsideRoot(root, filePath)) return null;
  try {
    let cursor = root;
    if (!(await fs.lstat(cursor)).isDirectory()) return null;
    for (const segment of path.relative(root, filePath).split(path.sep)) {
      cursor = path.join(cursor, segment);
      const stat = await fs.lstat(cursor);
      if (stat.isSymbolicLink()) return null;
    }
    const realRoot = await fs.realpath(root);
    const realFile = await fs.realpath(filePath);
    if (!isPathStrictlyInsideRoot(realRoot, realFile)) return null;
    const file = await fs.open(
      realFile,
      constants.O_RDONLY | constants.O_NOFOLLOW,
    );
    try {
      const stat = await file.stat();
      if (
        !stat.isFile() ||
        stat.nlink !== 1 ||
        stat.size === 0 ||
        stat.size > MAX_REFERENCE_IMAGE_BYTES
      )
        return null;
      const body = Buffer.alloc(stat.size);
      const { bytesRead } = await file.read(body, 0, body.length, 0);
      if (
        bytesRead !== body.length ||
        !matchesImageType(body, args.image.mimeType) ||
        createHash('sha256').update(body).digest('hex') !== args.image.hash
      )
        return null;
      return { body, mimeType: args.image.mimeType };
    } finally {
      await file.close();
    }
  } catch (error) {
    const code = errnoCode(error);
    if (['ENOENT', 'ENOTDIR', 'ELOOP', 'EACCES'].includes(code ?? ''))
      return null;
    throw error;
  }
};

export const readContextReferenceImage = async (args: {
  reference: VariantReference;
  context?: VariantWorkItemContext;
  roots: readonly string[];
}): Promise<ReferenceImage | null> => {
  const { reference, context } = args;
  if (!reference.image || !context) return null;
  const source = context.userContext.find(
    (candidate) =>
      candidate.transport === 'file' &&
      candidate.mimeType === reference.image?.mimeType &&
      candidate.references?.some(
        (item) =>
          item.id === reference.id &&
          item.url === reference.url &&
          item.image?.hash === reference.image?.hash,
      ),
  );
  if (!source || source.transport !== 'file') return null;
  for (const root of args.roots) {
    const image = await readReferenceImage({
      root,
      filePath: source.path,
      image: reference.image,
    });
    if (image) return image;
  }
  return null;
};
